/* The single-line text input operations that measure text with the widget's
   font, on a widget that has no canvas. The font lookup fails, the width
   service refuses the NULL font, and each operation must then position the
   text and cursor as for text of zero width.

   Before each call the stack below this function is filled with a nonzero
   pattern, so a width the operation reads without having set it is nonzero.
   Left to whatever an earlier call put there, the width of some operations
   happens to leave their results unchanged, and their checks would pass.  */

#include <stdio.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_single_line_text_input.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_single_line_text_input_no_canvas_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define OP_END                0
#define OP_HOME               1
#define OP_MARK_END           2
#define OP_MARK_HOME          3
#define OP_BACKSPACE          4
#define OP_CHARACTER_DELETE   5
#define OP_CHARACTER_INSERT   6
#define OP_TEXT_RECTANGLE_GET 7

typedef struct EXPECTED_STRUCT
{
    UINT     operation;
    ULONG    alignment;
    UINT     insert_pos;
    GX_VALUE xoffset;
    GX_VALUE cursor_x;
    UINT     new_insert_pos;
    UINT     new_size;
} EXPECTED;

static const EXPECTED expected[] = {
    {OP_END, GX_STYLE_TEXT_LEFT, 0, 0, 11, 4, 4},
    {OP_HOME, GX_STYLE_TEXT_LEFT, 4, 0, 11, 0, 4},
    {OP_MARK_END, GX_STYLE_TEXT_LEFT, 0, 0, 11, 4, 4},
    {OP_MARK_HOME, GX_STYLE_TEXT_LEFT, 4, 0, 11, 0, 4},
    {OP_BACKSPACE, GX_STYLE_TEXT_LEFT, 2, 0, 0, 1, 3},
    {OP_CHARACTER_DELETE, GX_STYLE_TEXT_LEFT, 2, 0, 0, 2, 3},
    {OP_CHARACTER_INSERT, GX_STYLE_TEXT_LEFT, 2, 0, 0, 3, 5},
    {OP_TEXT_RECTANGLE_GET, GX_STYLE_TEXT_LEFT, 2, 0, -1, 2, 4},
    {OP_END, GX_STYLE_TEXT_CENTER, 0, 0, 61, 4, 4},
    {OP_HOME, GX_STYLE_TEXT_CENTER, 4, 0, 61, 0, 4},
    {OP_MARK_END, GX_STYLE_TEXT_CENTER, 0, 0, 61, 4, 4},
    {OP_MARK_HOME, GX_STYLE_TEXT_CENTER, 4, 0, 61, 0, 4},
    {OP_BACKSPACE, GX_STYLE_TEXT_CENTER, 2, 0, 0, 1, 3},
    {OP_CHARACTER_DELETE, GX_STYLE_TEXT_CENTER, 2, 0, 0, 2, 3},
    {OP_CHARACTER_INSERT, GX_STYLE_TEXT_CENTER, 2, 0, 0, 3, 5},
    {OP_TEXT_RECTANGLE_GET, GX_STYLE_TEXT_CENTER, 2, 0, -1, 2, 4},
    {OP_END, GX_STYLE_TEXT_RIGHT, 0, 0, 108, 4, 4},
    {OP_HOME, GX_STYLE_TEXT_RIGHT, 4, 0, 108, 0, 4},
    {OP_MARK_END, GX_STYLE_TEXT_RIGHT, 0, 0, 108, 4, 4},
    {OP_MARK_HOME, GX_STYLE_TEXT_RIGHT, 4, 0, 108, 0, 4},
    {OP_BACKSPACE, GX_STYLE_TEXT_RIGHT, 2, 0, 0, 1, 3},
    {OP_CHARACTER_DELETE, GX_STYLE_TEXT_RIGHT, 2, 0, 0, 2, 3},
    {OP_CHARACTER_INSERT, GX_STYLE_TEXT_RIGHT, 2, 0, 0, 3, 5},
    {OP_TEXT_RECTANGLE_GET, GX_STYLE_TEXT_RIGHT, 2, 0, -1, 2, 4},
};

static UINT                      failed_tests = 0;
static GX_SINGLE_LINE_TEXT_INPUT input;
static GX_CHAR                   buffer[16];
static GX_RECTANGLE              input_size = {10, 10, 109, 39};

/* Fill the stack the operation under test will use with a nonzero pattern.  */
static VOID stack_fill(VOID)
{
volatile GX_UBYTE fill[4096];
UINT              index;

    for (index = 0; index < sizeof(fill); index++)
    {
        fill[index] = 0x55;
    }
}

static VOID input_reset(ULONG alignment, UINT insert_pos)
{
    strcpy(buffer, "abcd");
    input.gx_widget_style = (input.gx_widget_style & ~GX_STYLE_TEXT_ALIGNMENT_MASK) | alignment;
    input.gx_single_line_text_input_string_size = 4;
    input.gx_single_line_text_input_insert_pos = insert_pos;
    input.gx_single_line_text_input_start_mark = 0;
    input.gx_single_line_text_input_end_mark = 0;
    input.gx_single_line_text_input_xoffset = 0;
    input.gx_single_line_text_input_cursor_instance.gx_text_input_cursor_pos.gx_point_x = 0;
}

static UINT operation_run(UINT operation)
{
GX_RECTANGLE rect;
UINT         status = GX_FAILURE;

    stack_fill();

    switch (operation)
    {
    case OP_END:
        status = gx_single_line_text_input_end(&input);
        break;

    case OP_HOME:
        status = gx_single_line_text_input_home(&input);
        break;

    case OP_MARK_END:
        status = _gx_single_line_text_input_mark_end(&input);
        break;

    case OP_MARK_HOME:
        status = _gx_single_line_text_input_mark_home(&input);
        break;

    case OP_BACKSPACE:
        status = gx_single_line_text_input_backspace(&input);
        break;

    case OP_CHARACTER_DELETE:
        status = gx_single_line_text_input_character_delete(&input);
        break;

    case OP_CHARACTER_INSERT:
        status = gx_single_line_text_input_character_insert(&input, (GX_UBYTE *)"x", 1);
        break;

    case OP_TEXT_RECTANGLE_GET:
        status = _gx_single_line_text_input_text_rectangle_get(&input, 2, &rect);

        /* Report the rectangle through the fields the other operations set.  */
        input.gx_single_line_text_input_xoffset = rect.gx_rectangle_left;
        input.gx_single_line_text_input_cursor_instance.gx_text_input_cursor_pos.gx_point_x = rect.gx_rectangle_right;
        break;
    }

    return status;
}

VOID tx_application_define(void *first_unused_memory)
{
UINT            status;
UINT            index;
UINT            failed_before;
const EXPECTED *check;

    gx_system_initialize();

    /* No parent, so no canvas and no font.  */
    status = gx_single_line_text_input_create(&input, "input", GX_NULL, buffer, sizeof(buffer),
                                              GX_STYLE_BORDER_NONE, 1, &input_size);
    EXPECT_EQ(GX_SUCCESS, status);

    for (index = 0; index < sizeof(expected) / sizeof(expected[0]); index++)
    {
        check = &expected[index];
        failed_before = failed_tests;
        input_reset(check -> alignment, check -> insert_pos);
        status = operation_run(check -> operation);

        EXPECT_EQ(GX_SUCCESS, status);
        EXPECT_EQ(check -> xoffset, input.gx_single_line_text_input_xoffset);
        EXPECT_EQ(check -> cursor_x, input.gx_single_line_text_input_cursor_instance.gx_text_input_cursor_pos.gx_point_x);
        EXPECT_EQ(check -> new_insert_pos, input.gx_single_line_text_input_insert_pos);
        EXPECT_EQ(check -> new_size, input.gx_single_line_text_input_string_size);

        if (failed_tests != failed_before)
        {
            printf("Case %u: operation %u, alignment 0x%lx\n", index, check -> operation, check -> alignment);
        }
    }

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

#include "gx_validation_wrapper.h"
#include "demo_guix_all_widgets.c"
